import os
from pathlib import Path

def locate_profile_dir(profile_name: str, base_home: str) -> str:
    """Locate configuration profile directory. VULNERABLE: Searches CWD first."""
    cwd_profile = Path.cwd() / f".profile_{profile_name}"
    if cwd_profile.is_dir():
        return str(cwd_profile)
    sys_dir = Path(base_home) / ".profiles" / profile_name
    return str(sys_dir)

def get_manager_version() -> str:
